import pytest
from missing import find_missing


class TestFindMissingHappyPath:
    def test_missing_in_middle(self):
        assert find_missing([0, 1, 3]) == 2

    def test_missing_at_start(self):
        assert find_missing([1, 2, 3]) == 0

    def test_missing_at_end(self):
        assert find_missing([0, 1, 2]) == 3

    def test_simple_case(self):
        assert find_missing([0, 2]) == 1

    def test_larger_list(self):
        assert find_missing([0, 1, 2, 3, 4, 5, 7, 8, 9, 10]) == 6


class TestFindMissingEdgeCases:
    def test_empty_list(self):
        assert find_missing([]) == 0

    def test_single_element_zero(self):
        assert find_missing([0]) == 1

    def test_single_element_nonzero(self):
        assert find_missing([1]) == 0

    def test_two_elements_missing_first(self):
        assert find_missing([1]) == 0

    def test_two_elements_missing_last(self):
        assert find_missing([0]) == 1

    def test_consecutive_missing(self):
        """Test with numbers that appear to be consecutive but are from a valid sequence."""
        assert find_missing([5, 6, 7, 8, 9]) == 0
        assert find_missing([0, 1, 2, 3, 4]) == 5


class TestFindMissingErrorCases:
    def test_none_input(self):
        with pytest.raises(TypeError):
            find_missing(None)

    def test_non_iterable_input(self):
        with pytest.raises(TypeError):
            find_missing(5)

    def test_empty_string(self):
        """String is iterable but has no expected behavior for this function."""
        with pytest.raises(TypeError):
            find_missing("")

    def test_none_in_list(self):
        """List containing None is not a valid [0..n] sequence."""
        with pytest.raises(TypeError):
            find_missing([0, None, 2])

    def test_list_with_duplicates(self):
        """Duplicates violate the [0..n] unique sequence assumption."""
        with pytest.raises(TypeError):
            find_missing([0, 1, 1, 3])
